package owl.nh;
import java.util.*;
import net.unethicalite.api.widgets.Tab;

/** Dialogue and interface coordination, role targeting and recorded mirrored approach tests. */
public final class OlmEncounterFlowTests {
 static void check(boolean ok,String text){CoreTests.check(ok,"Olm encounter flow: "+text);}
 public static void main(String[] args)throws Exception{
  check(OlmFighter.transitionStyle(0)==CombatCore.Style.MAGIC&&OlmFighter.transitionStyle(1)==CombatCore.Style.MAGIC&&OlmFighter.transitionStyle(2)==CombatCore.Style.MELEE,"after two cleared hand pairs phase three prepares melee instead of regular-phase magic");
  ChambersDemonstration.Saved meleeDemo=new ChambersDemonstration.Saved();meleeDemo.actions=new ArrayList<>();OlmFighter.Profile meleeProfile=new OlmFighter.Profile();meleeProfile.mageHands.add(1);meleeProfile.meleeHands.add(2);for(int spawn:new int[]{10,30})for(int n=0;n<3;n++){ChambersDemonstration.Action action=new ChambersDemonstration.Action();action.option="Attack";action.targetNpcId=2;action.before=new ChambersDemonstration.Frame();action.before.x=spawn==10?15:25;action.before.y=20;action.before.npcs.add(new int[]{2,spawn,20,0,100,100,1});meleeDemo.actions.add(action);}Map<String,int[]> meleePlan=OlmArenaPlan.learnMelee(meleeDemo,meleeProfile);check(meleePlan.size()==2&&OlmArenaPlan.opposite(meleePlan,"10:20:0")[0]==25&&OlmArenaPlan.learn(meleeDemo,meleeProfile).isEmpty(),"phase-three approach is learned from opposite melee-hand attacks, without using mage positions");

  OlmEntryFlow f=new OlmEntryFlow();f.sentGate(1);
  check(f.next(2,true,false,true,true,false)==OlmEntryFlow.Action.CONTINUE,"continue prompt after first gate");f.sentContinue(2);
  check(f.next(3,true,false,true,true,false)==OlmEntryFlow.Action.WAIT,"same ignored Continue is not spammed");check(f.next(17,true,false,true,true,false)==OlmEntryFlow.Action.CONTINUE,"ignored Continue is retried without gate click");f.sentContinue(17);
  check(f.next(32,true,false,true,true,false)==OlmEntryFlow.Action.CONTINUE,"second message also gets Continue, never a gate");f.sentContinue(32);
  check(f.next(48,true,false,false,false,false)==OlmEntryFlow.Action.WAIT,"brief empty gap between dialogue pages never triggers a gate");check(f.next(60,true,false,true,true,false)==OlmEntryFlow.Action.CONTINUE,"late next page resets the clear interval");f.sentContinue(60);check(f.next(62,true,false,false,false,false)==OlmEntryFlow.Action.WAIT,"wait for stable dialogue dismissal");check(f.next(97,true,false,false,false,false)==OlmEntryFlow.Action.CLICK_GATE,"second entry attempt only after all dialogue clears");f.sentGate(97);
  check(f.next(98,true,false,true,true,false)==OlmEntryFlow.Action.CONTINUE,"second gate can also show Continue");f.sentContinue(98);check(f.stage()==OlmEntryFlow.Stage.WAIT_INSIDE,"second-entry continuation preserves crossing stage");
  check(f.next(114,true,false,false,true,false)==OlmEntryFlow.Action.CHOOSE_OPTION,"further entry options are handled without another gate click");f.sentOption(114);check(f.stage()==OlmEntryFlow.Stage.WAIT_INSIDE,"second-entry options also preserve crossing stage");check(f.next(116,true,false,false,false,true)==OlmEntryFlow.Action.WAIT&&f.stage()==OlmEntryFlow.Stage.INSIDE,"observed movement and cleared dialogue complete entry");
  check(OlmEntryFlow.entryOption(Arrays.asList("Leave","Yes, enter"))==2&&OlmEntryFlow.entryOption(Arrays.asList("Cancel","No"))==-1,"confirm entry without selecting a leave option");
  Map<String,Object> panel=new HashMap<>(),clientFields=new HashMap<>();panel.put("isVisible",false);clientFields.put("getWidget",ChambersTests.fake(net.runelite.api.widgets.Widget.class,panel));net.runelite.api.Client client=ChambersTests.fake(net.runelite.api.Client.class,clientFields);check(!VisibleCombatUi.contentOpen(client,Tab.INVENTORY)&&!VisibleCombatUi.contentOpen(client,Tab.PRAYER),"hidden content cannot count as an open inventory or prayer book");panel.put("isVisible",true);clientFields.put("getVarcIntValue",Tab.INVENTORY.ordinal());check(VisibleCombatUi.contentOpen(client,Tab.INVENTORY)&&!VisibleCombatUi.contentOpen(client,Tab.PRAYER),"cached visible Prayer widget cannot bypass Inventory selection");clientFields.put("getVarcIntValue",Tab.PRAYER.ordinal());check(!VisibleCombatUi.contentOpen(client,Tab.INVENTORY)&&VisibleCombatUi.contentOpen(client,Tab.PRAYER),"selected Prayer tab prevents hidden Inventory item actions even when cached widget reports visible");
  int[] cycle={100};EnumSet<Tab> open=EnumSet.of(Tab.INVENTORY);List<Tab> clicks=new ArrayList<>();VisibleCombatUi ui=new VisibleCombatUi(()->cycle[0],open::contains,clicks::add);
  check(!ui.ready(Tab.PRAYER,100)&&clicks.equals(Collections.singletonList(Tab.PRAYER)),"incoming prayer requests visible Prayer tab");cycle[0]++;check(!ui.ready(Tab.INVENTORY)&&clicks.size()==1,"inventory cannot reverse a pending defensive tab switch");open.clear();open.add(Tab.PRAYER);check(ui.ready(Tab.PRAYER,100),"visible Prayer content permits protection action");cycle[0]++;check(!ui.ready(Tab.INVENTORY)&&clicks.get(1)==Tab.INVENTORY,"inventory reopens after prayer action");cycle[0]++;check(!ui.ready(Tab.PRAYER)&&clicks.size()==2,"ordinary actions cannot flip a still-opening inventory");check(!ui.ready(Tab.PRAYER,100)&&clicks.get(2)==Tab.PRAYER,"new defensive prayer may preempt ordinary tab opening");
  OlmStrategy strategy=new OlmStrategy();for(int i=0;i<7;i++)strategy.drinkConfirmed();OlmStrategy.View v=OlmStrategyTests.ready();v.entered=true;v.hp=99;v.magicAlive=false;v.meleeAlive=true;v.phase=OlmStrategy.Phase.REGULAR;check(strategy.choose(v).value.equals("melee"),"mage down selects melee hand independently of left/right");
  OlmSpecials movement=new OlmSpecials();OlmSpecials.View mv=OlmSpecialsTests.view();mv.needsApproach=true;check(movement.choose(mv).context.equals("APPROACH"),"out-of-range hand produces approach movement without requiring a hazard");
  recordedPlan();
  if(args.length==2&&args[0].equals("--replay-demo")){try(java.io.Reader reader=java.nio.file.Files.newBufferedReader(java.nio.file.Paths.get(args[1]))){ChambersDemonstration.Saved saved=new com.google.gson.Gson().fromJson(reader,ChambersDemonstration.Saved.class);OlmFighter.Profile p=new OlmFighter.Profile();p.mageHands.add(7553);Map<String,int[]> plan=OlmArenaPlan.learn(saved,p);check(plan.size()==2,"real selected recording supplies both mirrored approach positions");System.out.println("Actual demonstration: two mirrored mage approaches learned; no live movement executed.");}}
  System.out.println("Olm encounter flow checks passed: multi-page dialogue, no gate during prompts, second-entry confirmations, tab preemption, melee approach and mirrored recorded preparation. Synthetic unless explicit replay selected.");
 }
 private static void recordedPlan(){ChambersDemonstration.Saved data=new ChambersDemonstration.Saved();data.actions=new ArrayList<>();OlmFighter.Profile profile=new OlmFighter.Profile();profile.mageHands.add(1);for(int spawn:new int[]{10,30})for(int n=0;n<3;n++){ChambersDemonstration.Action a=new ChambersDemonstration.Action();a.option="Attack";a.targetNpcId=1;a.before=new ChambersDemonstration.Frame();a.before.x=spawn==10?15:25;a.before.y=20;a.before.plane=0;a.before.npcs.add(new int[]{1,spawn,20,0,100,100,1});data.actions.add(a);}Map<String,int[]> plan=OlmArenaPlan.learn(data,profile);OlmArenaPlan.validate(plan);check(OlmArenaPlan.opposite(plan,"10:20:0")[0]==25&&OlmArenaPlan.opposite(plan,"30:20:0")[0]==15,"either spawn prepares its recorded opposite approach");check(OlmArenaPlan.opposite(plan,"unknown")==null,"unobserved geometry is not invented");}
}
